-- Synthetic-only ECG migration fixture. No production identifiers or secrets.
\set ON_ERROR_STOP on
BEGIN;
CREATE SCHEMA synthetic_ecg;
CREATE TABLE synthetic_ecg.accounts (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 display_name text NOT NULL,
 role_name text NOT NULL CHECK (role_name IN ('admin','reader')),
 active boolean NOT NULL DEFAULT true
);
CREATE TABLE synthetic_ecg.rooms (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 name text NOT NULL UNIQUE
);
CREATE TABLE synthetic_ecg.bookings (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 room_id bigint NOT NULL REFERENCES synthetic_ecg.rooms(id),
 actor_id bigint NOT NULL REFERENCES synthetic_ecg.accounts(id),
 starts_at timestamptz NOT NULL,
 ends_at timestamptz NOT NULL,
 CHECK (ends_at > starts_at)
);
CREATE TABLE synthetic_ecg.documents (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 owner_id bigint NOT NULL REFERENCES synthetic_ecg.accounts(id),
 content bytea NOT NULL,
 filename text NOT NULL,
 CHECK (octet_length(content) > 0)
);
INSERT INTO synthetic_ecg.accounts (display_name,role_name) VALUES
 ('Synthetic Admin','admin'), ('Synthetic Reader','reader');
INSERT INTO synthetic_ecg.rooms (name) VALUES ('Synthetic Hall'), ('Synthetic Library');
INSERT INTO synthetic_ecg.bookings(room_id,actor_id,starts_at,ends_at)
 VALUES (1,1,'2026-11-14 10:00+00','2026-11-14 11:00+00'),
        (2,2,'2026-11-15 11:00+00','2026-11-15 12:00+00');
INSERT INTO synthetic_ecg.documents(owner_id,filename,content) VALUES
 (1,'example.pdf',decode('255044462d312e340a2553594e5448455449430a','hex')),
 (2,'other.bin',decode('000102ff0a0d','hex'));
COMMIT;
